import { useContext, useEffect, useState, useCallback } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import './notifications.scss';

const Notifications = () => {
  const { currentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);
  const navigate = useNavigate();
  const [friendRequests, setFriendRequests] = useState([]);
  const [messageNotifications, setMessageNotifications] = useState([]);
  const [postNotifications, setPostNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [fetched, setFetched] = useState(false);

  console.log('Notifications: Initial render, currentUser=', currentUser ? JSON.stringify(currentUser, null, 2) : 'null');
  console.log('Notifications: sessionStorage.accessToken=', sessionStorage.getItem('accessToken') || 'null');

  const getProfilePictureUrl = (profilePicture) => {
    if (!profilePicture) {
      console.log('Notifications: No profile picture provided, using default');
      return '/assets/default-avatar.png';
    }
    if (profilePicture.startsWith('http')) {
      console.log('Notifications: Using external profile picture URL:', profilePicture);
      return profilePicture;
    }
    const normalizedPath = profilePicture
      .replace(/^\/(Uploads|post_upload|profile_upload)\//i, '/$1/')
      .replace(/^\/(post_upload|profile_upload)\//i, '/$1/');
    const url = `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
    console.log('Notifications: Profile picture URL:', url);
    return url;
  };

  const markNotificationsRead = async (token) => {
    try {
      // Mark post notifications (likes/comments) as read
      console.log('Notifications: Marking post notifications as read');
      await axios.post('http://localhost:5000/api/notifications/mark-read', {}, {
        headers: { Authorization: `Bearer ${token}` },
      });

      // Mark message notifications as read
      console.log('Notifications: Marking message notifications as read');
      await axios.post('http://localhost:5000/api/messages/mark-read', {}, {
        headers: { Authorization: `Bearer ${token}` },
      });

      console.log('Notifications: Notifications marked as read');
    } catch (err) {
      console.error('Notifications: Error marking notifications as read:', err.message);
      console.error('Notifications: Error details:', {
        status: err.response?.status,
        data: JSON.stringify(err.response?.data, null, 2),
      });
      setError('Failed to mark notifications as read.');
    }
  };

  const fetchNotifications = useCallback(async () => {
    setLoading(true);
    setError(null);
    const token = sessionStorage.getItem('accessToken');
    if (!token) {
      console.error('Notifications: No accessToken found in sessionStorage');
      setError('Please log in to view notifications.');
      setLoading(false);
      setFetched(true);
      navigate('/login');
      return;
    }

    try {
      // Fetch friend requests
      console.log('Notifications: Fetching friend requests from: http://localhost:5000/api/users/friend-requests/pending');
      const friendReqRes = await axios.get('http://localhost:5000/api/users/friend-requests/pending', {
        headers: { Authorization: `Bearer ${token}` },
      });
      const friendRequestsData = Array.isArray(friendReqRes.data) ? friendReqRes.data : [];
      console.log('Notifications: Friend requests response:', JSON.stringify(friendRequestsData, null, 2));

      const validatedFriendRequests = friendRequestsData.filter((req) => {
        const isValid = req.senderId &&
                       req.senderId._id &&
                       /^[0-9a-fA-F]{24}$/.test(req.senderId._id) &&
                       req.senderId.username &&
                       req.senderId.name &&
                       req.status === 'pending';
        if (!isValid) {
          console.warn('Notifications: Invalid friend request data:', JSON.stringify(req, null, 2));
        }
        return isValid;
      });
      console.log('Notifications: Validated friend requests:', JSON.stringify(validatedFriendRequests, null, 2));
      setFriendRequests(validatedFriendRequests);

      // Fetch message notifications
      console.log('Notifications: Fetching message notifications from: http://localhost:5000/api/messages/notifications');
      const msgRes = await axios.get('http://localhost:5000/api/messages/notifications', {
        headers: { Authorization: `Bearer ${token}` },
      });
      console.log('Notifications: Message notifications raw response:', JSON.stringify(msgRes.data, null, 2));
      if (!msgRes.data || !Array.isArray(msgRes.data)) {
        console.warn('Notifications: Invalid or empty message notifications response:', JSON.stringify(msgRes.data, null, 2));
        setMessageNotifications([]);
      } else {
        const validMessages = msgRes.data.filter((msg) => {
          const isValid = msg.senderId &&
                         msg.senderId._id &&
                         /^[0-9a-fA-F]{24}$/.test(msg.senderId._id) &&
                         msg.senderId.username &&
                         typeof msg.content === 'string' &&
                         msg.content.trim() &&
                         msg.senderId._id !== 'notifications';
          if (!isValid) {
            console.warn('Notifications: Skipping invalid message notification:', JSON.stringify(msg, null, 2));
          }
          return isValid;
        });
        console.log('Notifications: Validated message notifications:', JSON.stringify(validMessages, null, 2));
        setMessageNotifications(validMessages);
      }

      // Fetch post notifications (likes and comments)
      console.log('Notifications: Fetching post notifications from: http://localhost:5000/api/notifications');
      const postNotifRes = await axios.get('http://localhost:5000/api/notifications', {
        headers: { Authorization: `Bearer ${token}` },
      });
      console.log('Notifications: Post notifications raw response:', JSON.stringify(postNotifRes.data, null, 2));
      if (!postNotifRes.data || !Array.isArray(postNotifRes.data)) {
        console.warn('Notifications: Invalid or empty post notifications response:', JSON.stringify(postNotifRes.data, null, 2));
        setPostNotifications([]);
      } else {
        const validPostNotifications = postNotifRes.data.filter((notif) => {
          const isValid = notif.senderId &&
                         notif.senderId._id &&
                         /^[0-9a-fA-F]{24}$/.test(notif.senderId._id) &&
                         notif.senderId.username &&
                         ['like', 'comment'].includes(notif.type) &&
                         notif.postId &&
                         /^[0-9a-fA-F]{24}$/.test(notif.postId);
          if (!isValid) {
            console.warn('Notifications: Skipping invalid post notification:', JSON.stringify(notif, null, 2));
          }
          return isValid;
        });
        console.log('Notifications: Validated post notifications:', JSON.stringify(validPostNotifications, null, 2));
        setPostNotifications(validPostNotifications);
      }

      // Mark notifications as read
      await markNotificationsRead(token);

      setError(null);
      setFetched(true);
    } catch (err) {
      console.error('Notifications: Error fetching notifications:', err.message);
      console.error('Notifications: Error details:', {
        status: err.response?.status,
        data: JSON.stringify(err.response?.data, null, 2),
      });
      let errorMessage = 'Failed to load notifications. Please try again.';
      if (err.response?.status === 401) {
        errorMessage = 'Session expired. Please log in again.';
        sessionStorage.removeItem('accessToken');
        sessionStorage.removeItem('user');
        navigate('/login');
      } else if (err.response?.status === 404) {
        errorMessage = 'No notifications found.';
        setFriendRequests([]);
        setMessageNotifications([]);
        setPostNotifications([]);
      }
      setError(errorMessage);
      setFetched(true);
    } finally {
      setLoading(false);
      console.log('Notifications: fetchNotifications completed, loading=', false);
    }
  }, [navigate]);

  useEffect(() => {
    if (!currentUser) {
      console.log('Notifications: No currentUser, redirecting to login');
      setError('Please log in to view notifications.');
      navigate('/login');
      return;
    }
    console.log('Notifications: Fetching notifications for user:', currentUser.id || currentUser._id);
    fetchNotifications();
    const interval = setInterval(fetchNotifications, 10000);
    return () => {
      console.log('Notifications: Cleaning up polling interval');
      clearInterval(interval);
    };
  }, [currentUser, fetchNotifications, navigate]);

  const handleFriendRequestAction = async (senderId, action) => {
    try {
      const token = sessionStorage.getItem('accessToken');
      if (!token) {
        throw new Error('No access token available');
      }
      const status = action === 'accept' ? 'accepted' : 'rejected';
      console.log(`Notifications: ${action}ing friend request from senderId: ${senderId}`);
      const res = await axios.post(
        `http://localhost:5000/api/users/friend-requests/${senderId}`,
        { action: status },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      console.log(`Notifications: Friend request ${status}:`, res.data);
      setFriendRequests(friendRequests.filter((req) => req.senderId._id !== senderId));
      alert(`Friend request ${status} successfully!`);
    } catch (err) {
      console.error(`Notifications: Error ${action}ing friend request:`, err.message);
      console.error('Notifications: Error details:', {
        status: err.response?.status,
        data: JSON.stringify(err.response?.data, null, 2),
      });
      const errorMessage = err.response?.data?.message || `Failed to ${action} friend request.`;
      setError(errorMessage);
    }
  };

  const handleMessageClick = (senderId) => {
    console.log('Notifications: handleMessageClick called with senderId:', senderId);
    if (!senderId || !/^[0-9a-fA-F]{24}$/.test(senderId) || senderId === 'notifications') {
      console.error('Notifications: Invalid senderId for navigation:', senderId);
      setError('Invalid user ID for message navigation.');
      return;
    }
    console.log('Notifications: Navigating to messages for senderId:', senderId);
    navigate(`/messages/${senderId}`);
  };

  const handlePostNotificationClick = (postId) => {
    console.log('Notifications: handlePostNotificationClick called with postId:', postId);
    if (!postId || !/^[0-9a-fA-F]{24}$/.test(postId)) {
      console.error('Notifications: Invalid postId for navigation:', postId);
      setError('Invalid post ID for navigation.');
      return;
    }
    console.log('Notifications: Navigating to post:', postId);
    navigate(`/post/${postId}`);
  };

  console.log('Notifications: Rendering with state:', {
    loading,
    error,
    fetched,
    friendRequests: friendRequests.length,
    messageNotifications: messageNotifications.map(msg => ({
      _id: msg._id,
      senderId: msg.senderId?._id,
      username: msg.senderId?.username,
      content: msg.content,
    })),
    postNotifications: postNotifications.map(notif => ({
      _id: notif._id,
      senderId: notif.senderId?._id,
      type: notif.type,
      postId: notif.postId,
      content: notif.content,
    })),
  });

  if (!currentUser) {
    console.log('Notifications: Rendering no currentUser state');
    return <div className={`notifications ${darkMode ? 'theme-dark' : 'theme-light'}`}>Please log in to view notifications.</div>;
  }

  return (
    <div className={`notifications ${darkMode ? 'theme-dark' : 'theme-light'}`}>
      <h3>Notifications</h3>
      {loading && <p className="loading">Loading notifications...</p>}
      {error && <p className="error">{error}</p>}
      {fetched && !loading && !error && 
       friendRequests.length === 0 && 
       messageNotifications.length === 0 && 
       postNotifications.length === 0 && (
        <p className="no-notifications">No new notifications.</p>
      )}
      <div className="notifications-list">
        {friendRequests.length > 0 && (
          <div className="notification-section">
            <h4>Friend Requests</h4>
            {friendRequests.map((request) => (
              <div key={`friend-${request.senderId._id}`} className="notification-card">
                <div className="notification-info">
                  <img
                    src={getProfilePictureUrl(request.senderId.profilePicture)}
                    alt={`${request.senderId.username}'s profile`}
                    className="avatar"
                    onError={(e) => {
                      console.error(`Notifications: Image load error for ${request.senderId.username}:`, e);
                      e.target.src = '/assets/default-avatar.png';
                    }}
                  />
                  <div className="details">
                    <span className="username">{request.senderId.username}</span>
                    <span className="message">{request.senderId.name} sent you a friend request</span>
                  </div>
                </div>
                <div className="actions">
                  <button
                    className="accept-btn"
                    onClick={() => handleFriendRequestAction(request.senderId._id, 'accept')}
                    disabled={loading}
                  >
                    Accept
                  </button>
                  <button
                    className="reject-btn"
                    onClick={() => handleFriendRequestAction(request.senderId._id, 'reject')}
                    disabled={loading}
                  >
                    Reject
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
        {messageNotifications.length > 0 && (
          <div className="notification-section">
            <h4>Messages</h4>
            {messageNotifications.map((msg) => {
              const isValidSenderId = msg.senderId?._id && /^[0-9a-fA-F]{24}$/.test(msg.senderId._id) && msg.senderId._id !== 'notifications';
              console.log('Notifications: Rendering message notification:', {
                _id: msg._id,
                senderId: msg.senderId?._id,
                isValidSenderId,
                username: msg.senderId?.username,
                content: msg.content,
              });
              return (
                <div key={`message-${msg._id}`} className="notification-card message-notification">
                  <div
                    className="notification-info"
                    onClick={() => isValidSenderId && handleMessageClick(msg.senderId._id)}
                    style={{ cursor: isValidSenderId ? 'pointer' : 'not-allowed', opacity: isValidSenderId ? 1 : 0.5 }}
                  >
                    <img
                      src={getProfilePictureUrl(msg.senderId.profilePicture)}
                      alt={`${msg.senderId.username || 'Unknown'}'s profile`}
                      className="avatar"
                      onError={(e) => {
                        console.error(`Notifications: Image load error for ${msg.senderId.username || 'Unknown'}:`, e);
                        e.target.src = '/assets/default-avatar.png';
                      }}
                    />
                    <div className="details">
                      <span className="username">{msg.senderId.username || 'Unknown User'}</span>
                      <span className="message">New message: {msg.content || 'No content'}</span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
        {postNotifications.length > 0 && (
          <div className="notification-section">
            <h4>Post Activity</h4>
            {postNotifications.map((notif) => {
              const isValidPostId = notif.postId && /^[0-9a-fA-F]{24}$/.test(notif.postId);
              console.log('Notifications: Rendering post notification:', {
                _id: notif._id,
                senderId: notif.senderId?._id,
                type: notif.type,
                postId: notif.postId,
                isValidPostId,
                username: notif.senderId?.username,
                content: notif.content,
                read: notif.read,
              });
              return (
                <div key={`post-${notif._id}`} className="notification-card post-notification">
                  <div
                    className="notification-info"
                    onClick={() => isValidPostId && handlePostNotificationClick(notif.postId)}
                    style={{ cursor: isValidPostId ? 'pointer' : 'not-allowed', opacity: isValidPostId ? 1 : 0.5 }}
                  >
                    <img
                      src={getProfilePictureUrl(notif.senderId.profilePicture)}
                      alt={`${notif.senderId.username || 'Unknown'}'s profile`}
                      className="avatar"
                      onError={(e) => {
                        console.error(`Notifications: Image load error for ${notif.senderId.username || 'Unknown'}:`, e);
                        e.target.src = '/assets/default-avatar.png';
                      }}
                    />
                    <div className="details">
                      <span className="username">{notif.senderId.username || 'Unknown User'}</span>
                      <span className="message">
                        {notif.type === 'like'
                          ? `${notif.senderId.name} liked your post`
                          : `${notif.senderId.name} commented on your post: ${notif.content || 'No content'}`}
                      </span>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default Notifications;
